qp.Set( 1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f );
Validate( qp.GetQuaternion() == Quaternion(1.0f, 2.0f, 3.0f, 4.0f) &&
          qp.GetPos() == Vector3(5.0f, 6.0f, 7.0f) );



