SetFunctionName("Set(float_test_typeRef<QUAT_XSRC_INDEX> _QuatX, float_test_typeRef<QUAT_YSRC_INDEX> _QuatY, float_test_typeRef<QUAT_ZSRC_INDEX> _QuatZ, float_test_typeRef<QUAT_WSRC_INDEX> _QuatW, float_test_typeRef<POS_XSRC_INDEX> _PosX, float_test_typeRef<POS_YSRC_INDEX> _PosY, float_test_typeRef<POS_ZSRC_INDEX> _PosZ)");
