SetFunctionName("QuatPos Select(MaskScalar mask, QuatPos a, QuatPos b)");
const QuatPos qp1(1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f);
const QuatPos qp2(12.0f, 12.0f, 13.0f, 14.0f, 15.0f, 16.0f, 17.0f);

QuatPos result1 = Select( MaskScalar(true), qp1, qp2 );
QuatPos result2 = Select( MaskScalar(false), qp1, qp2 );
Validate(
    result1 == qp1 &&
    result2 == qp2
);



SetFunctionName("IsSimilar(QuatPos a,  QuatPos b, epsilon)");
QuatPos qp1(1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f );
QuatPos qp2(1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.1f );

Validate( !IsSimilar(qp1, qp2) &&
          !IsSimilar(qp1, qp2, (float_test_type)0.09f) &&
           IsSimilar(qp1, qp2, (float_test_type)0.11f) );



// on SPU, NaN operations evaluates to 0
#if !defined EA_PLATFORM_PS3_SPU
        {
            SetFunctionName("IsValid(QuatPos a,  QuatPos b, epsilon)");
            QuatPos qp1(1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f );

            QuatPos qp2((float)testing::GetNaN(), 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.01f );
            QuatPos qp3(1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, (float)testing::GetNaN() );

            Validate(  IsValid(qp1) &&
                      !IsValid(qp2) &&
                      !IsValid(qp3) );
        }
#endif



SetFunctionName("Mult(QuatPos a, QuatPos b)");
QuatPos qp1(1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f );
QuatPos qp2(3.0f, 2.0f, 1.0f, 0.0f, -1.0f, -2.0f, -3.0f );
// Note: These numbers were generated by running Mult on the input.
// This test case will only ensure future changes don't modify the results generated.
QuatPos ref(8.0f, 16.0f, 0.0f, -10.0f, 4.0f, 4.0f, 4.0f );

QuatPos result = Mult(qp1, qp2);

Validate( IsSimilar( result, ref, (float_test_type)0.001f ) );




SetFunctionName("Inverse(QuatPos a)");

QuatPos qp1(4.0f, 3.0f, 2.0f, -3.0f, 5.0f, 6.0f, 7.0f );
QuatPos qp_compare;
Inverse(qp1.quat, qp_compare.quat);
Vector3Transform(qp_compare.quat, qp1.pos, qp_compare.pos);
Negate(qp_compare.pos, qp_compare.pos);

QuatPos qp2 = Inverse(qp1);
QuatPos multiply_qp2_qp1 = Mult(qp2, qp1);
QuatPos identity = GetQuatPos_Identity();
Validate(
        IsEqualWithEpsilon((float_basic_type)qp2.quat.X(), (float_basic_type)-0.105263f) &&
        IsEqualWithEpsilon((float_basic_type)qp2.quat.Y(), (float_basic_type)-0.078947f) &&
        IsEqualWithEpsilon((float_basic_type)qp2.quat.Z(), (float_basic_type)-0.052632f) &&
        IsEqualWithEpsilon((float_basic_type)qp2.quat.W(), (float_basic_type)-0.078947f) &&
        IsEqualWithEpsilon((float_basic_type)qp2.quat.X(), (float_basic_type)qp_compare.quat.X()) &&
        IsEqualWithEpsilon((float_basic_type)qp2.quat.Y(), (float_basic_type)qp_compare.quat.Y()) &&
        IsEqualWithEpsilon((float_basic_type)qp2.quat.Z(), (float_basic_type)qp_compare.quat.Z()) &&
        IsEqualWithEpsilon((float_basic_type)qp2.quat.W(), (float_basic_type)qp_compare.quat.W()) &&
        IsSimilar(qp2.pos, qp_compare.pos) &&
        IsSimilar(multiply_qp2_qp1.quat, identity.quat) &&
        IsSimilar(multiply_qp2_qp1.pos, identity.pos)
);



SetFunctionName("QuatPosFromMatrix44(Matrix44::InParam)");
Quaternion quat = Normalize(Quaternion(1.0f, 2.0f, 3.0f, 1.5f));
Vector3 position( -4.0f, 7.0f, 9.0f );
Matrix44 matrix = Matrix44FromQuaternionTranslation(quat, position);
QuatPos result = QuatPosFromMatrix44( matrix );

Validate( IsSimilar( result.GetQuaternion(), quat, (float_test_type)0.001f ) &&
          IsSimilar( result.GetPos(), position, (float_test_type)0.001f) );



SetFunctionName("Matrix44FromQuatPos(QuatPos::InParam)");
QuatPos qp( Normalize(Quaternion(1.0f, 2.0f, 3.0f, 1.5f)),
            Vector3( -4.0f, 7.0f, 9.0f ) );
Matrix44 result = Matrix44FromQuatPos(qp);
QuatPos qp2 = QuatPosFromMatrix44( result );

Validate( IsSimilar( qp, qp2, (float_test_type)0.001f) );



SetFunctionName("QuatPosFromMatrix44Affine(Matrix44Affine::InParam)");
