Vector3 position( -4.0f, 7.0f, 9.0f );
Matrix44Affine matrix = Matrix44AffineFromQuaternionTranslation(quat, position);
QuatPos result = QuatPosFromMatrix44Affine( matrix );

Validate( IsSimilar( result.GetQuaternion(), quat, (float_test_type)0.001f ) &&
          IsSimilar( result.GetPos(), position, (float_test_type)0.001f) );



SetFunctionName("Matrix44AffineFromQuatPos(QuatPos::InParam)");
QuatPos qp( Normalize(Quaternion(1.0f, 2.0f, 3.0f, 1.5f)),
            Vector3( -4.0f, 7.0f, 9.0f ) );
