SetFunctionName("TransformPoint(Vector3 point, QuatPos q)");
QuatPos qp( Normalize(Quaternion(1.0f, 2.0f, 3.0f, 1.5f)),
            Vector3( -4.0f, 7.0f, 9.0f ) );
Matrix44 mat = Matrix44FromQuatPos(qp);
Vector3 point(5.0f, 4.0f, -3.0f);
Vector3 ref = TransformPoint( point, mat );
Vector3 result = TransformPoint( point, qp );

Validate( IsSimilar( ref, result, (float_test_type)0.001f) );



SetFunctionName("QuatPosGetMatrix44AffineRowX(QuatPos::InParam quat)");
QuatPos qp(1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f);
Matrix44 mat= Matrix44FromQuaternion(qp.GetQuaternion());
Vector3 ref = GetXYZ(mat.XAxis());
Vector3 result = QuatPosGetMatrix44AffineRowX(qp);

Validate( IsSimilar(result, ref) );



