SetFunctionName("QuatPosFromAxisRotationAngle(Vector3 axis, VecFloat lrAngleInRadians)");

Vector3 axis( SQRT_HALF, SQRT_HALF, 0);
QuatPos ref( 0.5f, 0.5f, 0.0f, SQRT_HALF,
             0.0f, 0.0f, 0.0f );

QuatPos result = QuatPosFromAxisRotationAngle(axis, (float_test_type)HALF_PI);

