SetFunctionName("QuatPos&      operator = (QuatPos::InParam v)");
QuatPos qpRef( 1.0f, 2.1f, 3.2f, 4.3f, 5.0f, 6.0f, 7.0f );
QuatPos qp;
qp= qpRef;
Validate((float)qp.GetQuaternion().X() == 1.0f && (float)qp.GetQuaternion().Y() == 2.1f && (float)qp.GetQuaternion().Z() == 3.2f && (float)qp.GetQuaternion().W() == 4.3f
&& (float)qp.GetPos().X() == 5.0f && (float)qp.GetPos().Y() == 6.f && (float)qp.GetPos().Z() == 7.f);



SetFunctionName("operator ==(QuatPos::InParam a,           QuatPos::InParam b)");
QuatPos qp1(1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f );
QuatPos qp2(1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f );
QuatPos qp3(1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.3f, 7.0f );

Validate(   qp1 == qp2  &&
          !(qp2 == qp3) );



SetFunctionName("operator !=(QuatPos::InParam a,           QuatPos::InParam b)");
QuatPos qp1(1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f );
QuatPos qp2(1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f );
QuatPos qp3(1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.3f, 7.0f );

Validate( !(qp1 != qp2) &&
            qp2 != qp3  );
